-- InzuLink marketplace schema (canonical — matches server.js at HEAD).
-- Rebuilt 2026-11-16. The previous Neon schema belonged to the retired
-- student-housing generation and could not run this backend.
-- Status-like columns are TEXT on purpose: the app uses several lifecycles
-- (Available/Sold for trading, Pending/Approved/Rejected for moderation).
-- Restore: psql "$DATABASE_URL" -f schema.sql

CREATE TABLE IF NOT EXISTS "users" (
  "user_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_name" TEXT NOT NULL,
  "email" TEXT NOT NULL UNIQUE,
  "phone" TEXT NOT NULL,
  "nida_number" TEXT,
  "password" TEXT NOT NULL,
  "role" TEXT NOT NULL DEFAULT 'Seeker',
  "is_verified_agent" BOOLEAN NOT NULL DEFAULT FALSE,
  "subscription_plan" TEXT NOT NULL DEFAULT 'Free',
  "status" TEXT NOT NULL DEFAULT 'Active',
  "reset_token" TEXT,
  "reset_expires" TIMESTAMPTZ,
  "subscription_end_date" TIMESTAMPTZ,
  "pro_request_status" TEXT,
  "pro_payment_phone" TEXT,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS "properties" (
  "property_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "owner_id" INTEGER NOT NULL REFERENCES "users"("user_id") ON DELETE CASCADE,
  "title" TEXT NOT NULL,
  "description" TEXT,
  "district" TEXT,
  "sector" TEXT,
  "cell" TEXT,
  "village" TEXT,
  "price_per_month" NUMERIC NOT NULL DEFAULT 0,
  "bedrooms" INTEGER NOT NULL DEFAULT 0,
  "listing_type" TEXT NOT NULL DEFAULT 'Rent',
  "category" TEXT NOT NULL DEFAULT 'House',
  "upi" TEXT,
  "land_size" NUMERIC NOT NULL DEFAULT 0,
  "contact_phone" TEXT,
  "latitude" NUMERIC,
  "longitude" NUMERIC,
  "status" TEXT NOT NULL DEFAULT 'Available',
  "status_updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  "views_count" INTEGER NOT NULL DEFAULT 0,
  "is_featured" BOOLEAN NOT NULL DEFAULT FALSE,
  "is_deleted" BOOLEAN NOT NULL DEFAULT FALSE,
  "rejection_reason" TEXT,
  "promotion_status" TEXT NOT NULL DEFAULT 'None',
  "payer_phone" TEXT,
  "video_path" TEXT,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "idx_properties_owner" ON "properties"("owner_id");
CREATE INDEX IF NOT EXISTS "idx_properties_status" ON "properties"("status");
CREATE INDEX IF NOT EXISTS "idx_properties_featured" ON "properties"("is_featured") WHERE "is_featured";

CREATE TABLE IF NOT EXISTS "propertyimages" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "property_id" INTEGER NOT NULL REFERENCES "properties"("property_id") ON DELETE CASCADE,
  "image_path" TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS "idx_propertyimages_property" ON "propertyimages"("property_id");

CREATE TABLE IF NOT EXISTS "reviews" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "property_id" INTEGER NOT NULL REFERENCES "properties"("property_id") ON DELETE CASCADE,
  "user_id" INTEGER NOT NULL REFERENCES "users"("user_id") ON DELETE CASCADE,
  "rating" INTEGER NOT NULL CHECK ("rating" BETWEEN 1 AND 5),
  "comment" TEXT,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE ("property_id", "user_id")
);
CREATE INDEX IF NOT EXISTS "idx_reviews_property" ON "reviews"("property_id");

CREATE TABLE IF NOT EXISTS "contractlogs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "landlord_name" TEXT,
  "tenant_name" TEXT,
  "tenant_id" TEXT,
  "property_district" TEXT,
  "rent_amount" NUMERIC NOT NULL DEFAULT 0,
  "generated_at" TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS "transactions" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" INTEGER REFERENCES "users"("user_id") ON DELETE SET NULL,
  "amount" NUMERIC NOT NULL DEFAULT 0,
  "phone_number" TEXT,
  "payment_type" TEXT,
  "status" TEXT NOT NULL DEFAULT 'Pending',
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "idx_transactions_user" ON "transactions"("user_id");

CREATE TABLE IF NOT EXISTS "jobs" (
  "job_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" TEXT NOT NULL,
  "description" TEXT,
  "application_link" TEXT,
  "status" TEXT NOT NULL DEFAULT 'Open',
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS "favorites" (
  "user_id" INTEGER NOT NULL REFERENCES "users"("user_id") ON DELETE CASCADE,
  "property_id" INTEGER NOT NULL REFERENCES "properties"("property_id") ON DELETE CASCADE,
  "saved_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY ("user_id", "property_id")
);

CREATE TABLE IF NOT EXISTS "searchlogs" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "term" TEXT NOT NULL,
  "created_at" TIMESTAMPTZ NOT NULL DEFAULT now()
);
